let annotationColor=load('highlight-color','yellow');
if(!palette[annotationColor])annotationColor='yellow';
function textOffset(paragraph,node,offset){const r=document.createRange();r.selectNodeContents(paragraph);r.setEnd(node,offset);return r.toString().length}
function captureSelection(selection){if(!selection||selection.isCollapsed||!selection.toString().trim()||!selection.rangeCount)return null;const content=document.querySelector('#reading-content'),range=selection.getRangeAt(0);if(!content?.contains(range.startContainer)||!content.contains(range.endContainer))return null;
  const anchors=[...content.querySelectorAll('p[data-par]')].filter(p=>range.intersectsNode(p)).map(p=>{const start=p.contains(range.startContainer)?textOffset(p,range.startContainer,range.startOffset):0,end=p.contains(range.endContainer)?textOffset(p,range.endContainer,range.endOffset):p.textContent.length;return {par:p.dataset.par,start,end,text:p.textContent.slice(start,end)}}).filter(a=>a.end>a.start&&a.text.trim());
  return anchors.length?{quote:selection.toString().trim().slice(0,20000),anchors,rect:range.getBoundingClientRect()}:null;
}
function annotationPanel(draft,rect,editingKey=null){document.querySelector('.selection-tools')?.remove();const panel=document.createElement('div');panel.className='selection-tools annotation-popover';panel.setAttribute('role','dialog');panel.setAttribute('aria-label',editingKey?'Sửa highlight và ghi chú':'Lưu highlight và ghi chú');let color=palette[draft.color]?draft.color:annotationColor;
  panel.innerHTML=`<div class="annotation-top"><span>${editingKey?'CHỈNH SỬA GHI CHÚ':'GIỮ LẠI MỘT Ý TƯỞNG'}</span><button class="close-annotation" aria-label="Đóng">×</button></div>${editingKey?`<blockquote>${esc(draft.quote||'Ghi chú cá nhân')}</blockquote>`:''}<textarea id="annotation-note" maxlength="5000" aria-label="Ghi chú cho đoạn chọn" placeholder="Điều gì khiến bạn chú ý? Thêm một ghi chú…">${esc(draft.text||'')}</textarea><div class="annotation-bottom"><span class="annotation-mode">${svg('highlight')}<span>Highlight & Note</span></span><div class="annotation-colors" role="group" aria-label="Màu highlight">${Object.entries(palette).map(([id,c])=>`<button type="button" class="color-swatch ${id===color?'active':''}" style="--swatch:${c.hex}" data-color="${id}" aria-label="Màu ${c.name}" aria-pressed="${id===color}"></button>`).join('')}</div><button class="save-annotation" aria-label="Lưu highlight và ghi chú" title="Lưu highlight và ghi chú">${svg('highlight')}<span>Lưu</span></button></div><span class="annotation-tip">${editingKey?'Đổi màu hoặc bổ sung suy nghĩ của bạn.':'Đoạn được chọn sẽ được lưu cùng vị trí trong bài.'}</span>`;
  panel.style.left=Math.max(12,Math.min(rect.left,innerWidth-Math.min(570,innerWidth-24)-12))+'px';panel.style.top=Math.max(12,Math.min(rect.bottom+12,innerHeight-230))+'px';panel.querySelector('.close-annotation').onclick=()=>panel.remove();panel.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{color=b.dataset.color;panel.querySelectorAll('[data-color]').forEach(s=>{s.classList.toggle('active',s.dataset.color===color);s.setAttribute('aria-pressed',String(s.dataset.color===color))})});
  panel.querySelector('.save-annotation').onclick=()=>{if(!canSavePersonal()){toast('Chờ tải dữ liệu tài khoản trước khi lưu.');return}const record={...draft,key:editingKey||crypto.randomUUID(),id:state.id,color,text:panel.querySelector('textarea').value.trim(),createdAt:draft.createdAt||new Date().toISOString()};delete record.rect;if(!record.quote&&!record.text){toast('Viết một ghi chú trước khi lưu.');return}if(editingKey)notes=notes.map(n=>n.key===editingKey?record:n);else notes.push(record);persist('notes',notes);annotationColor=color;persist('highlight-color',color);panel.remove();window.getSelection()?.removeAllRanges();render();toast(editingKey?'Đã cập nhật ghi chú.':'Đã lưu highlight vào ghi chú.')};document.body.append(panel);
}
function showSelection(event){if(event?.target?.closest?.('.selection-tools'))return;if(state.view!=='reader'){document.querySelector('.selection-tools')?.remove();return}const selection=window.getSelection();const captured=captureSelection(selection);if(!captured){if(!event?.target?.closest?.('mark'))document.querySelector('.selection-tools')?.remove();return}if(!canSavePersonal())return;annotationPanel(captured,captured.rect)}
function editNote(key){const note=notes.find(n=>n.key===key);if(!note)return;if(state.view!=='reader'||state.id!==note.id){openItem(note.id)}const sidebar=document.querySelector('.reader-rail')?.getBoundingClientRect();annotationPanel(note,{left:Math.max(20,innerWidth/2-280),bottom:Math.min(innerHeight-240,sidebar?.top||150)},key)}
function normalizedAnchors(note,paragraphs){if(Array.isArray(note.anchors))return note.anchors;if(note.par!==undefined&&note.quote){const p=paragraphs.find(p=>p.dataset.par===String(note.par));const start=p?.textContent.indexOf(note.quote)??-1;return start>=0?[{par:String(note.par),start,end:start+note.quote.length,text:note.quote}]:[]}return []}
restoreHighlights=function(){
  const container=document.querySelector('#reading-content');if(!container)return;
  const paragraphs=[...container.querySelectorAll('p[data-par]')];
  for(const p of paragraphs){for(const mark of p.querySelectorAll('mark'))mark.replaceWith(...mark.childNodes)}
  const local=notes.filter(n=>n.id===state.id&&n.quote);
  const all=local.flatMap(n=>normalizedAnchors(n,paragraphs).map(a=>({...a,note:n})));
  for(const p of paragraphs){const text=p.textContent;const ranges=all.filter(a=>String(a.par)===p.dataset.par).flatMap(a=>{let start=Number(a.start),end=Number(a.end);if(!Number.isInteger(start)||!Number.isInteger(end)||start<0||end<=start||end>text.length)return [];if(a.text&&text.slice(start,end)!==a.text){start=text.indexOf(a.text);if(start<0)return [];end=start+a.text.length}return [{start,end,note:a.note}]});if(!ranges.length)continue;
    // Count every text node for stable offsets, but preserve math/code markup.
    const walker=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),nodes=[];let node,cursor=0;
    while(node=walker.nextNode()){nodes.push({node,start:cursor,end:cursor+node.textContent.length,skip:!!node.parentElement.closest('.math-source,code')});cursor+=node.textContent.length}
    for(const record of nodes){if(record.skip)continue;const matches=ranges.filter(r=>r.start<record.end&&r.end>record.start);if(!matches.length)continue;
      const raw=record.node.textContent,bounds=[...new Set([0,raw.length,...matches.flatMap(r=>[Math.max(0,r.start-record.start),Math.min(raw.length,r.end-record.start)])])].sort((a,b)=>a-b),fragment=document.createDocumentFragment();
      for(let i=0;i<bounds.length-1;i++){const start=bounds[i],end=bounds[i+1],active=matches.filter(r=>r.start<=record.start+start&&r.end>=record.start+end);if(!active.length){fragment.append(document.createTextNode(raw.slice(start,end)));continue}const note=active.at(-1).note,mark=document.createElement('mark');mark.textContent=raw.slice(start,end);mark.style.backgroundColor=palette[note.color]?.bg||palette.yellow.bg;mark.dataset.noteKey=note.key;mark.tabIndex=0;mark.setAttribute('role','button');mark.setAttribute('aria-label','Sửa highlight: '+(note.text||note.quote).slice(0,100));mark.title=note.text||'Bấm để sửa highlight';mark.onclick=()=>{if(!window.getSelection()?.toString().trim())editNote(note.key)};mark.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();editNote(note.key)}};fragment.append(mark)}record.node.replaceWith(fragment)
    }
    for(const math of p.querySelectorAll('.math-source')){const prefix=document.createRange();prefix.selectNodeContents(p);prefix.setEndBefore(math);const start=prefix.toString().length,end=start+math.textContent.length,note=ranges.filter(r=>r.start<end&&r.end>start).at(-1)?.note;math.style.backgroundColor=note?(palette[note.color]?.bg||palette.yellow.bg):'';if(note){math.dataset.noteKey=note.key;math.onclick=()=>{if(!window.getSelection()?.toString().trim())editNote(note.key)}}}
  }
};
document.addEventListener('keyup',event=>{if(event.key==='Shift')showSelection(event)});
document.addEventListener('touchend',event=>{setTimeout(()=>showSelection(event),100)},{passive:true});
render();
